-- MP-0042: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='bersatu' and type='party') then raise exception 'MP-0042: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0042: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0042: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('muhyiddin-yassin','syed-ibrahim-syed-noh','tan-hong-pin') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0042: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('pagoh','ledang','bakri') and slug not in ('muhyiddin-yassin','syed-ibrahim-syed-noh','tan-hong-pin')) then raise exception 'MP-0042: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0042:%' and (m.source_type <> 'editorial' or e.slug not in ('muhyiddin-yassin','syed-ibrahim-syed-noh','tan-hong-pin') or m.import_key not like 'MP-0042:' || e.slug || ':%')) then raise exception 'MP-0042: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'muhyiddin-yassin','Muhyiddin Yassin','opposition','Member of the Dewan Rakyat; President of Bersatu','Pagoh','Johor','Muhyiddin Yassin represents Pagoh, Johor, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; President of Bersatu. Affiliated with Bersatu. Also recorded by Parliament as Mahiaddin Md Yasin.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4182','/portraits/muhyiddin-yassin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P143.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4182"}, {"label": "Bersatu · October CSA signatory and opposition status", "url": "https://www.bernama.com/bm/am/news.php?id=2627381"}]'::jsonb from public.entities parent where parent.slug='bersatu' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'syed-ibrahim-syed-noh','Syed Ibrahim Syed Noh','government','Deputy Minister of Natural Resources and Environmental Sustainability','Ledang','Johor','Syed Ibrahim Syed Noh represents Ledang, Johor, in the Dewan Rakyat. Current role: Deputy Minister of Natural Resources and Environmental Sustainability. Affiliated with PKR.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4183','/portraits/syed-ibrahim-syed-noh.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P144.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4183"}, {"label": "PKR · current parliamentary representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'tan-hong-pin','Tan Hong Pin','government','Member of the Dewan Rakyat','Bakri','Johor','Tan Hong Pin represents Bakri, Johor, in the Dewan Rakyat. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4184','/portraits/tan-hong-pin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P145.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4184"}, {"label": "DAP · current Johor representatives", "url": "https://dapmalaysia.org/johor-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('muhyiddin-yassin','syed-ibrahim-syed-noh','tan-hong-pin') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0042: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0042:syed-ibrahim-syed-noh:dgirt-pilot-vehicle-launch','Launch the DGIRT geospatial response pilot vehicle','Governance','achieved',null,null,null,null,'2026-10-29','https://www.bernama.com/bm/wilayah/news.php?id=2627304','Syed Ibrahim launched the dedicated vehicle developed by JUPEM with the Armed Forces to combine geospatial instruments, drones and field-response equipment.','Achieved is limited to the reported pilot launch. It does not certify fleet-wide deployment, response-time improvements or the deputy minister’s sole responsibility.','2026-11-10','editorial',false from public.entities e where e.slug='syed-ibrahim-syed-noh' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0042:muhyiddin-yassin:budget-2027-csa','Support Supply Bill 2027 under the confidence-and-supply agreement','Governance',null,null,null,'2026-10-29','https://www.bernama.com/bm/am/news.php?id=2627381',null,null,'Signed the agreement committing support for the 2027 Supply Bill.','The agreement is documented. A subsequent budget vote or final passage was not established in this pass; signing is not counted as delivery of the bill or joining another party.','2026-11-10','editorial',false from public.entities e where e.slug='muhyiddin-yassin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

